    (divUniversalMultiplierFibreEquiv (π := pi) C hpi g K
        (1 ⊗ₜ[k] a) : (relCurve C K).functionField) *
      (divUniversalHighWindowClosedAmbientFibreEquiv
        (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j K n x :
