import AlgebraicJacobian.Picard.DivSchemeHighWindowFibreNormalization
import AlgebraicJacobian.Picard.DivSchemeHighWindowRelationFlat
import AlgebraicJacobian.Picard.DivSchemeProjectiveFibreModel
import AlgebraicJacobian.Picard.DivSchemeHighWindowImageTransfer

/-!
# Fibre models for the recursive high-window relations

The closed normalization identifies a scalar-extended high-window ambient with
`H^0(N + nS)`.  The divisor reconstructed from the carve point cuts out a
canonical subspace `H^0(N + nS - D)` inside that ambient.  This file packages
the equality saying that a relative relation has precisely that image on a
field fibre, and uses projectivity of the relative quotient to turn the image
equality into an equivalence of relation fibres.

No base case or persistence recurrence is proved here.
-/

set_option autoImplicit false
set_option quotPrecheck false
set_option backward.isDefEq.respectTransparency false
set_option maxSynthPendingDepth 8
set_option maxRecDepth 10000
set_option linter.unusedSectionVars false

universe u

open CategoryTheory Limits TopologicalSpace Opposite
open scoped TensorProduct

namespace AlgebraicGeometry

open Scheme Grassmannian

attribute [local instance] Scheme.overModule Scheme.overSectionsAlgebra
  Scheme.functionFieldOverModule
attribute [local instance 10000] relCurve.instOver

section HighWindowFibreModel

variable {k : Type u} [Field k] (C : Over (Spec (.of k)))
  [SmoothOfRelativeDimension 1 C.hom] [IsProper C.hom]
  [GeometricallyIrreducible C.hom]
variable {pi : C.left ⟶ P1 k} [IsFinite pi] [IsDominant pi]

noncomputable local instance instOverCleftHighWindowFibreModel :
    C.left.Over (Spec (.of k)) := ⟨C.hom⟩

variable [SmoothOfRelativeDimension 1 (C.left ↘ Spec (.of k))] [IsIntegral C.left]
  [LocallyOfFiniteType (C.left ↘ Spec (.of k))]
  [QuasiCompact (C.left ↘ Spec (.of k))]
  [Module.Finite k (Sheaf.HModule (C.left.moduleKSheaf k) 0)]
  [Module.Finite k (Sheaf.HModule (C.left.moduleKSheaf k) 1)]
variable (hpi : pi ≫ P1.structureMap k = C.left ↘ Spec (CommRingCat.of k))
variable (g r1 r2 : Nat)
variable (b1 : Module.Basis (Fin r1) k
  ↥(Scheme.divisorSections k
    (windowM_choice pi hpi g • fiberWeilDivisor pi) ⊤))
variable (b2 : Module.Basis (Fin r2) k
  ↥(Scheme.divisorSections k
    ((windowS_choice pi hpi g • fiberWeilDivisor pi) +
      (windowM_choice pi hpi g • fiberWeilDivisor pi)) ⊤))
variable (i : (glueData k g r1).J) (j : (glueData k g r2).J)

local notation "RP" => PairChartRing k g r1 g r2 i j
local notation "RZ" => DivCarveChartRing k
  (windowS_choice pi hpi g • fiberWeilDivisor pi)
  (windowM_choice pi hpi g • fiberWeilDivisor pi) g r1 r2 b1 b2 i j
local notation "G[" n "]" => divUniversalHighWindowAmbient
  (C := C) (pi := pi) (hpi := hpi) (g := g)
    (r1 := r1) (r2 := r2) (b1 := b1) (b2 := b2) (i := i) (j := j) n
local notation "Kr[" n "]" => divUniversalHighWindowRelation
  (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j n

variable (K : Type u) [Field K] [Algebra k K]
  [Algebra RP K] [IsScalarTower k RP K]
  [Algebra RZ K] [IsScalarTower RP RZ K] [IsScalarTower k RZ K]

noncomputable local instance instIsIntegralRelCurveHighWindowFibreModel :
    IsIntegral (relCurve C K) := instIsIntegralBaseChange C K

noncomputable local instance instSmoothRelCurveHighWindowFibreModel :
    SmoothOfRelativeDimension 1 (relCurve C K ↘ Spec (CommRingCat.of K)) :=
  instSmoothOfRelativeDimensionBaseChange C K

noncomputable local instance instQCRelCurveHighWindowFibreModel :
    QuasiCompact (relCurve C K ↘ Spec (CommRingCat.of K)) :=
  instQuasiCompactBaseChange C K

noncomputable local instance instLFTRelCurveHighWindowFibreModel :
    LocallyOfFiniteType (relCurve C K ↘ Spec (CommRingCat.of K)) :=
  haveI : Smooth (relCurve C K ↘ Spec (CommRingCat.of K)) :=
    SmoothOfRelativeDimension.smooth 1 _
  inferInstance

noncomputable local instance instFinH0RelCurveHighWindowFibreModel :
    Module.Finite K (Sheaf.HModule ((relCurve C K).moduleKSheaf K) 0) :=
  instModuleFiniteHModuleZeroBaseChange C K

noncomputable local instance instFinH1RelCurveHighWindowFibreModel :
    Module.Finite K (Sheaf.HModule ((relCurve C K).moduleKSheaf K) 1) :=
  instModuleFiniteHModuleOneBaseChange C K

variable (hO : Sheaf.h0 (C.left.moduleKSheaf k) = 1)
  (hchi : Sheaf.chi (C.left.moduleKSheaf k) = 1 - (g : ℤ))
  (hker : divCarveIdeal k
      (windowS_choice pi hpi g • fiberWeilDivisor pi)
      (windowM_choice pi hpi g • fiberWeilDivisor pi)
      g r1 r2 b1 b2 i j ≤ RingHom.ker (algebraMap RP K))

/-! ## The canonical fibre window inside the closed ambient -/

set_option maxHeartbeats 1600000 in
-- Expanding the reconstructed divisor and its high-window section module is expensive.
/-- The divisor fibre window `H^0(N+nS-D)` is contained in the closed ambient
`H^0(N+nS)`. -/
theorem divUniversalFibreHighWindow_le_closedAmbient (n : Nat) :
    divUniversalFibreHighWindow
        C hpi g r1 r2 b1 b2 i j K hO hchi hker n ≤
      Scheme.divisorSections K
        (windowN C K hpi g + n • windowS C K hpi g) ⊤ := by
  rw [divUniversalFibreHighWindow]
  exact Scheme.divisorSections_mono K
    (sub_le_self _ (divUniversalFibreDivisor_spec
      C hpi g r1 r2 b1 b2 i j K hO hchi hker).1) ⊤

set_option maxHeartbeats 1600000 in
-- The comap target contains the full closed-normalization campaign parameters.
/-- The canonical divisor fibre window, regarded as a submodule of its closed
high-window ambient rather than of the whole function field. -/
noncomputable def divUniversalFibreHighWindowInAmbient (n : Nat) :
    Submodule K
      ↥(Scheme.divisorSections K
        (windowN C K hpi g + n • windowS C K hpi g) ⊤) :=
  (divUniversalFibreHighWindow
    C hpi g r1 r2 b1 b2 i j K hO hchi hker n).comap
      (Scheme.divisorSections K
        (windowN C K hpi g + n • windowS C K hpi g) ⊤).subtype

set_option maxHeartbeats 1600000 in
-- Elaborating both nested section-submodule subtype structures exceeds the default budget.
/-- Forgetting the closed-ambient wrapper identifies the in-ambient window
with the original function-field submodule. -/
noncomputable def divUniversalFibreHighWindowInAmbientEquiv (n : Nat) :
    ↥(divUniversalFibreHighWindowInAmbient
        C hpi g r1 r2 b1 b2 i j K hO hchi hker n) ≃ₗ[K]
      ↥(divUniversalFibreHighWindow
        C hpi g r1 r2 b1 b2 i j K hO hchi hker n) where
  toFun x := ⟨x.1.1, x.2⟩
  invFun x := ⟨⟨x.1, divUniversalFibreHighWindow_le_closedAmbient
    C hpi g r1 r2 b1 b2 i j K hO hchi hker n x.2⟩, x.2⟩
  left_inv x := by
    apply Subtype.ext
    apply Subtype.ext
    rfl
  right_inv x := by
    apply Subtype.ext
    rfl
  map_add' x y := by
    apply Subtype.ext
    rfl
  map_smul' a x := by
    apply Subtype.ext
    rfl

set_option maxHeartbeats 1600000 in
-- Reducing the custom equivalence through both subtype coercions is elaboration-heavy.
@[simp]
theorem divUniversalFibreHighWindowInAmbientEquiv_coe (n : Nat)
    (x : ↥(divUniversalFibreHighWindowInAmbient
      C hpi g r1 r2 b1 b2 i j K hO hchi hker n)) :
    ((divUniversalFibreHighWindowInAmbientEquiv
        C hpi g r1 r2 b1 b2 i j K hO hchi hker n x :
      divUniversalFibreHighWindow
        C hpi g r1 r2 b1 b2 i j K hO hchi hker n) :
      (relCurve C K).functionField) = x.1.1 :=
  rfl

/-! ## Fieldwise and residue-prime image predicates -/

set_option maxHeartbeats 1600000 in
-- The equality expands the relative ambient, normalization, and reconstructed divisor.
/-- At a carve-killing field point, the relative relation has the expected
canonical divisor window as its image in the closed normalized ambient. -/
def DivUniversalHighWindowFibreImage (n : Nat) : Prop :=
  Submodule.map
      (divUniversalHighWindowClosedAmbientFibreEquiv
        (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j K n).toLinearMap
      (Kr[n].baseChange K) =
    divUniversalFibreHighWindowInAmbient
      C hpi g r1 r2 b1 b2 i j K hO hchi hker n

set_option maxHeartbeats 2000000 in
set_option synthInstance.maxHeartbeats 800000 in
-- The canonical four-step scalar tower at each residue field needs the campaign budget.
/-- The fibre-model condition at a relative stage: the expected image equality
holds over the residue field of every prime of the carve-chart ring. -/
def DivUniversalHighWindowFibreModel (n : Nat) : Prop :=
  ∀ p : PrimeSpectrum RZ,
    DivUniversalHighWindowFibreImage
      C hpi g r1 r2 b1 b2 i j p.asIdeal.ResidueField hO hchi
        (divCarveIdeal_le_ker_of_tower k
          (windowS_choice pi hpi g • fiberWeilDivisor pi)
          (windowM_choice pi hpi g • fiberWeilDivisor pi)
          g r1 r2 b1 b2 i j p.asIdeal.ResidueField) n

/-! ## Projective relation fibres -/

set_option maxHeartbeats 2000000 in
set_option synthInstance.maxHeartbeats 800000 in
-- Projective base change unfolds the dependent relation and normalized ambient types.
/-- A projective relative quotient and the fieldwise image equality identify
the scalar extension of the relation itself with the canonical divisor fibre
window. -/
noncomputable def divUniversalHighWindowRelationFibreEquiv (n : Nat)
    [Module.Projective RZ (G[n] ⧸ Kr[n])]
    (himage : DivUniversalHighWindowFibreImage
      C hpi g r1 r2 b1 b2 i j K hO hchi hker n) :
    K ⊗[RZ] ↥Kr[n] ≃ₗ[K]
      ↥(divUniversalFibreHighWindow
        C hpi g r1 r2 b1 b2 i j K hO hchi hker n) :=
  (Grassmannian.projectiveQuotientFibreModelEquiv Kr[n]
    (divUniversalHighWindowClosedAmbientFibreEquiv
      (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j K n)
    (divUniversalFibreHighWindowInAmbient
      C hpi g r1 r2 b1 b2 i j K hO hchi hker n) himage).trans
    (divUniversalFibreHighWindowInAmbientEquiv
      C hpi g r1 r2 b1 b2 i j K hO hchi hker n)

set_option maxHeartbeats 2400000 in
set_option synthInstance.maxHeartbeats 800000 in
-- Rewriting the composite equivalence through nested function-field coercions is expensive.
/-- The relation fibre equivalence is the normalized ambient read after
scalar-extending the relation inclusion. -/
@[simp]
theorem divUniversalHighWindowRelationFibreEquiv_coe (n : Nat)
    [Module.Projective RZ (G[n] ⧸ Kr[n])]
    (himage : DivUniversalHighWindowFibreImage
      C hpi g r1 r2 b1 b2 i j K hO hchi hker n)
    (x : K ⊗[RZ] ↥Kr[n]) :
    ((divUniversalHighWindowRelationFibreEquiv
        C hpi g r1 r2 b1 b2 i j K hO hchi hker n himage x :
      divUniversalFibreHighWindow
        C hpi g r1 r2 b1 b2 i j K hO hchi hker n) :
      (relCurve C K).functionField) =
    ((divUniversalHighWindowClosedAmbientFibreEquiv
        (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j K n
      (LinearMap.baseChange K Kr[n].subtype x) :
        Scheme.divisorSections K
          (windowN C K hpi g + n • windowS C K hpi g) ⊤) :
      (relCurve C K).functionField) := by
  rw [divUniversalHighWindowRelationFibreEquiv, LinearEquiv.trans_apply,
    divUniversalFibreHighWindowInAmbientEquiv_coe,
    Grassmannian.projectiveQuotientFibreModelEquiv_coe]

end HighWindowFibreModel

end AlgebraicGeometry
